package cpamp

import "sort"

type QuotaAttribution struct {
	Status            string   `json:"status"`
	Percent           *float64 `json:"percent"`
	ObservedDelta     float64  `json:"observed_delta"`
	UnattributedDelta float64  `json:"unattributed_delta"`
	From              int64    `json:"from_ms"`
	Through           int64    `json:"through_ms"`
	Reason            string   `json:"reason"`
}

// A quota snapshot is not a request debit. Under an explicit gateway-only
// assumption, only intervals involving exactly one recorded key are attributed.
// Ambiguous/concurrent keys, boundary requests and the pre-baseline allowance
// remain unassigned. No token or dollar weighting is substituted for metering.
func attributeKeyQuota(w Window, observations []Observation, events []Event, key string, gatewayOnly bool) QuotaAttribution {
	r := QuotaAttribution{Status: "unavailable", Reason: "Account quota can include other apps. Enable the gateway-only assumption to estimate single-key meter intervals."}
	if key == "" {
		if w.Final == nil {
			r.Reason = "The provider did not report a utilization value for this window."
			return r
		}
		r.Status, r.Percent, r.Reason = "reported", w.Final, "Provider-reported account quota."
		return r
	}
	if !gatewayOnly {
		return r
	}
	if w.BoundaryRevision || w.ClockSkew > 0 || w.Straddling > 0 || w.BoundaryUncertain > 0 {
		r.Reason = "Reset or request timing is ambiguous; quota attribution is unavailable."
		return r
	}
	ids := map[string]bool{}
	for _, id := range w.ObservationIDs {
		ids[id] = true
	}
	obs := []Observation{}
	for _, o := range observations {
		if ids[o.ID] && o.Used != nil && finite(*o.Used) && *o.Used >= 0 && *o.Used <= 100 {
			obs = append(obs, o)
		}
	}
	sort.SliceStable(obs, func(i, j int) bool { return obs[i].Observed < obs[j].Observed })
	if len(obs) < 2 {
		r.Reason = "At least two quota observations in this window are required."
		return r
	}
	first, last := obs[0], obs[len(obs)-1]
	r.From, r.Through = first.Observed, last.Observed
	if *last.Used >= 100 {
		r.Reason = "The quota meter is saturated; subsequent debits cannot be measured."
		return r
	}
	base := first
	plan := first.PlanType
	assigned, eligible := 0.0, 0
	for _, o := range obs[1:] {
		if plan != "" && o.PlanType != "" && plan != o.PlanType {
			r.Reason = "The subscription changed inside this window; its quota denominator is not stable."
			return r
		}
		if o.PlanType != "" {
			plan = o.PlanType
		}
		delta := *o.Used - *base.Used
		if delta < 0 {
			r.Reason = "Quota decreased inside this window; reset or correction requires separate evidence."
			return r
		}
		if delta == 0 {
			continue
		}
		r.ObservedDelta += delta
		keys := map[string]bool{}
		ambiguous := false
		low, high := observationPoint(base), observationPoint(o)
		if !timedPoint(low) || !timedPoint(high) {
			ambiguous = true
		}
		for _, e := range events {
			if !inWindow(e, w) || e.Started > high.TimeHigh || e.Completed < low.TimeLow {
				continue
			}

			if e.Completed < e.Started {
				ambiguous = true
			}
			k := e.APIKeyHash
			if keyMatches(e, key) {
				k = key
			}
			if k == "" {
				k = UnknownAPIKey
			}
			keys[k] = true
		}
		if !ambiguous && len(keys) == 1 {
			eligible++
			if keys[key] {
				assigned += delta
			}
		} else {
			r.UnattributedDelta += delta
		}
		base = o
	}
	if eligible == 0 {
		r.Reason = "No unambiguous single-key meter intervals; tokens and API-equivalent cost are still recorded."
		return r
	}
	r.Percent, r.Status = &assigned, "partial_estimate"
	r.Reason = "Attributed meter increases only. Assumes no usage outside this gateway and timely provider accounting; rounding and reporting lag remain uncertain."
	complete := *first.Used == 0 && r.UnattributedDelta == 0
	for _, e := range events {
		if inWindow(e, w) && (e.Started < first.Observed || e.Completed > last.Observed) {
			complete = false
		}
	}
	if complete {
		r.Status = "estimate"
	}
	return r
}
